SELECT * FROM finance_records

    deleted = 0

        AND record_no LIKE CONCAT('%', #{recordNo}, '%')


        AND record_type = #{recordType}


        AND record_category = #{recordCategory}


        AND payment_method = #{paymentMethod}


        AND counterparty_name LIKE CONCAT('%', #{counterpartyName}, '%')


        AND business_date >= #{startDate}


        AND business_date <= #{endDate}


        AND approval_status = #{approvalStatus}


ORDER BY create_time DESC

SELECT COALESCE(SUM(amount), 0) FROM finance_records
WHERE deleted = 0
  AND record_type = #{recordType}

      AND business_date >= #{startDate}


      AND business_date <= #{endDate}
